CREATE OR REPLACE FUNCTION calculate_sri(p_scanresolmm numeric, p_pointdense numeric)
RETURNS numeric AS $$
BEGIN
    -- Handle NULL or non-positive inputs
    IF p_scanresolmm IS NULL OR p_pointdense IS NULL THEN
        RETURN NULL;
    END IF;

    IF p_scanresolmm <= 0 OR p_pointdense <= 0 THEN
        RETURN NULL;
    END IF;

    -- SRI = log10(scanresolmm * 1000) / log10(pointdense) * 5
    RETURN (LOG(p_scanresolmm * 1000) / LOG(10)) / (LOG(p_pointdense) / LOG(10)) * 5;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_sri(p_cloudregistry bigint)
RETURNS numeric AS $$
DECLARE
    v_scanresolmm numeric;
    v_pointdense numeric;
BEGIN
    SELECT scanresolmm, pointdense INTO v_scanresolmm, v_pointdense
    FROM scanpointcloud
    WHERE cloudregistry = p_cloudregistry;

    -- Handle NULL or non-positive inputs
    IF v_scanresolmm IS NULL OR v_pointdense IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_scanresolmm <= 0 OR v_pointdense <= 0 THEN
        RETURN NULL;
    END IF;

    -- SRI = log10(scanresolmm * 1000) / log10(pointdense) * 5
    RETURN (LOG(v_scanresolmm * 1000) / LOG(10)) / (LOG(v_pointdense) / LOG(10)) * 5;
END;
$$ LANGUAGE plpgsql;

