CREATE OR REPLACE FUNCTION calculate_sri(p_scanresolmm numeric, p_pointdense numeric)
RETURNS numeric AS $$
BEGIN
    IF p_scanresolmm IS NULL OR p_pointdense IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_scanresolmm <= 0 OR p_pointdense <= 0 THEN
        RETURN NULL;
    END IF;
    RETURN (LOG(CAST(p_scanresolmm * 1000 AS numeric)) / LOG(10.0)) / (LOG(CAST(p_pointdense AS numeric)) / LOG(10.0)) * 5;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION sri_quality_category(sri_val numeric)
RETURNS text AS $$
BEGIN
    IF sri_val IS NULL THEN
        RETURN 'Unknown';
    ELSIF sri_val < 2.0 THEN
        RETURN 'Excellent';
    ELSIF sri_val < 3.0 THEN
        RETURN 'Good';
    ELSIF sri_val < 4.0 THEN
        RETURN 'Fair';
    ELSE
        RETURN 'Poor';
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION test_sri_functions(p_scanresolmm numeric, p_pointdense numeric)
RETURNS TABLE(sri_value numeric, quality_category text) AS $$
BEGIN
    RETURN QUERY
    SELECT calculate_sri(p_scanresolmm, p_pointdense) AS sri_value,
           sri_quality_category(calculate_sri(p_scanresolmm, p_pointdense)) AS quality_category;
END;
$$ LANGUAGE plpgsql;
